/**
 * UI views. `unread`, `lastMessage` and the preview list are DERIVED here (they were
 * stored, and the stored copy disagreed with the messages on 3/5 avatars — D12).
 * Nothing below is authored: every field comes from a record above.
 *
 * Instants stay ISO. `data/` holds no formatted string and no clock reading — a relative
 * label computed here would be baked in at module load (server) and again in the browser,
 * and the two disagree at the first unit boundary (React error #418). The UI formats with
 * `formatRelative()` / `formatDayHeading()` from `content/core.ts`, which measure against
 * the fixture clock (`DEMO_NOW_ISO`), so every label is a pure function of the ISO value.
 */
export const mockContacts = contacts.map((contact) => ({
  id: contact.id,
  name: contact.name,
  status: contact.status,
  ...(contact.lastSeenAt ? { lastSeenAt: contact.lastSeenAt } : {}),
}));

export const mockConversations = conversations.map((conversation) => ({
  id: conversation.id,
  contactId: conversation.contactId,
  unread: deriveUnread(conversation),
  lastMessage: (() => {
    const last = deriveLastMessage(conversation);
    return { text: last.body ?? "", timestamp: last.sentAt };
  })(),
  messages: conversation.messages.map((message) => ({
    id: message.id,
    senderId: message.senderId,
    ...(message.body ? { text: message.body } : {}),
    ...(message.image ? { image: message.image.src } : {}),
    timestamp: message.sentAt,
    status: message.status,
  })),
}));

export const recentMessages = selectRecentMessages(conversations, contacts).map((row) => ({
  id: `${row.conversationId}-preview`,
  conversationId: row.conversationId,
  sender: row.person.name,
  content: row.lastMessage.body ?? "",
  lastMessageAt: row.lastMessageAt,
  unread: row.hasUnread,
}));

/** One row of the header's messages drawer. */
export type RecentMessage = (typeof recentMessages)[number];

/**
 * The conversations this brand's messages drawer shows (issue #156 follow-up).
 *
 * The five sample conversations above are the quiz product's: a quiz tournament, a quiz meetup,
 * a science quiz. The header is chrome on every route of both builds, so on `BRAND=alignsynch`
 * they rendered a whole quiz conversation list above an alignment front page. This build has no
 * conversations behind that drawer — nothing in `data/` is one — so it gets an empty list and the
 * drawer draws its empty state (the words are `messages`' `empty-title` / `empty-body`).
 *
 * An empty list rather than a second set of invented alignment conversations: a fixture of
 * messages nobody sent is the mock this repo keeps deleting, and the drawer's own empty state is
 * already the screen for "you have no conversations".
 */
export function recentMessagesFor(brandId: BrandId): readonly RecentMessage[] {
  switch (brandId) {
    case "quizhub":
      return recentMessages;
    case "alignsynch":
      return [];
    default: {
      // A brand added to `data/brand.ts` without a drawer decision fails `tsc` here.
      const unhandled: never = brandId;
      throw new Error(`no messages drawer for brand ${String(unhandled)}`);
    }
  }
}
